<script setup>
import { onMounted, ref } from 'vue'
import { getSessions, getSessionReport } from '../api/client'
const sessions = ref([]); const selected = ref(null); const report = ref(null); const loading = ref(true); const errorMessage = ref('')
async function openReport(session) { try { selected.value = session; report.value = await getSessionReport(session.id) } catch (e) { errorMessage.value = e.message } }
onMounted(async () => { try { sessions.value = await getSessions(); if (sessions.value[0]) await openReport(sessions.value[0]) } catch (e) { errorMessage.value = e.message } finally { loading.value = false } })
</script>
<template><main class="app-shell"><header class="topbar"><div><RouterLink class="back-link-inline" to="/teacher">← 返回老师工作台</RouterLink><p class="eyebrow">LIVE REPORTS</p><h1>即时统计</h1><p class="muted">查看每一场课堂的提交分布和正确情况，不显示具体学生身份。</p></div></header><p v-if="loading" class="loading-state">正在读取统计…</p><p v-else-if="errorMessage" class="error-message">{{ errorMessage }}</p><section v-else class="reports-layout"><aside class="report-sessions"><h2>课堂场次</h2><button v-for="item in sessions" :key="item.id" :class="{ active: selected?.id === item.id }" class="choice-row" @click="openReport(item)"><span>{{ item.question_sets?.name || '题目集合' }}<small>{{ item.classes?.name || item.classes?.code || '' }}</small></span><small>{{ item.status === 'closed' ? '已结束' : item.status }}</small></button><p v-if="!sessions.length" class="empty-state">目前还没有课堂场次。</p></aside><section v-if="report" class="report-panel"><div class="report-summary"><span>已加入 <strong>{{ report.participant_count }}</strong> 台设备</span><span>总提交 <strong>{{ report.total_submitted_count }}</strong> 次</span></div><article v-for="question in report.questions" :key="question.id" class="report-question"><div class="report-question-heading"><div><span class="question-number">{{ question.sort_order }}</span><strong>{{ question.question_text || '图片题目' }}</strong></div><span>正确率 {{ question.accuracy }}%</span></div><div class="report-bars"><div v-for="key in ['A','B','C','D']" :key="key" class="report-bar"><span>{{ key }}</span><div><i :style="{ width: `${question.submitted_count ? question.distribution[key] / question.submitted_count * 100 : 0}%` }"></i></div><b>{{ question.distribution[key] }}</b></div></div><p class="helper-text">已提交 {{ question.submitted_count }} 人，答对 {{ question.correct_count }} 人</p></article></section></section></main></template>
